M="biochem-lab"
SUB="Laboratory Techniques"
T={
"pcr":[("The DNA polymerase used in PCR is taken from Thermus aquaticus because it is:",["Heat stable","Highly processive","Free of exonuclease","Active without primers"],0,"It survives the denaturation step, so fresh enzyme is not needed each cycle."),
 ("The three steps of each PCR cycle are:",["Denaturation, annealing, extension","Annealing, denaturation, extension","Extension, denaturation, annealing","Denaturation, extension, annealing"],0,"Roughly 95, 55 and 72 degrees respectively."),
 ("To measure a patient's viral RNA load by PCR, the first additional step required is:",["Reverse transcription to cDNA","Digestion with a restriction enzyme","Hybridisation to a labelled probe","Separation by gel electrophoresis"],0,"DNA polymerase cannot copy RNA, so the template must first be converted.",3)],
"crispr":[("In the CRISPR/Cas9 system, target specificity is provided by:",["A guide RNA","The Cas9 protein","A restriction enzyme","A labelled DNA probe"],0,"Retargeting the system means synthesising a new guide, not redesigning a protein."),
 ("The CRISPR system originally evolved as:",["A bacterial defence against viruses","A plasmid replication system","A eukaryotic repair pathway","A mechanism of gene silencing"],0,"Bacteria store fragments of previous invaders to recognise them again."),
 ("To correct rather than disrupt a gene with CRISPR, the cell must repair the cut by:",["Homology directed repair","Nonhomologous end joining","Base excision repair","Mismatch repair"],0,"A donor template must be supplied; simple end joining loses bases and knocks the gene out instead.",3)],
"blot":[("A Southern blot detects:",["DNA","RNA","Protein","Carbohydrate"],0,"The technique is named after its inventor, Edward Southern."),
 ("Which blot uses an antibody as the detecting reagent?",["Western","Southern","Northern","Southwestern"],0,"It is an immunoblot for a protein immobilised after electrophoresis."),
 ("To find out whether a gene is being actively expressed in a tissue, the appropriate blot is:",["Northern","Southern","Western","Southwestern"],0,"Messenger RNA abundance is what reports transcription, and that is what this blot measures.",2)],
"elisa":[("Flow cytometry differs from ELISA in that it:",["Analyses one cell at a time","Uses antibodies for detection","Requires a fluorescent label","Measures protein rather than DNA"],0,"ELISA reports a total amount across the whole sample."),
 ("Counting CD4 cells in a patient with HIV is performed by:",["Flow cytometry","ELISA","Southern blot","Microarray"],0,"Individual cells must be identified and counted, which only this method does."),
 ("Why is an HIV screening test followed by a different confirmatory test?",["The screen favours sensitivity over specificity","The screen cannot detect early infection","The confirmatory test is cheaper to run","The screen measures antigen not antibody"],0,"A screen is designed to miss as few true cases as possible, which produces false positives that a more specific test then excludes.",3)],
"karyo":[("Conventional karyotyping cannot detect abnormalities smaller than roughly:",["5 million base pairs","5 thousand base pairs","500 base pairs","50 base pairs"],0,"Submicroscopic deletions need FISH or microarray instead."),
 ("Karyotyping requires cells that are:",["Actively dividing","Fixed in interphase","Freshly lysed","Free of nuclei"],0,"Chromosomes are only visible when condensed at metaphase."),
 ("Chromosomal microarray has replaced karyotyping for many indications but still cannot detect:",["A balanced translocation","A submicroscopic deletion","A submicroscopic duplication","An extra whole chromosome"],0,"No genetic material is gained or lost, so the total amount of DNA looks entirely normal.",3)],
"array":[("A microarray measuring gene expression is hybridised with:",["Labelled cDNA made from sample RNA","Genomic DNA cut by restriction enzymes","Antibodies against sample proteins","Unlabelled ribosomal RNA"],0,"Brightness at each spot reports how strongly that gene is expressed."),
 ("The advantage of a microarray over a Northern blot is that it:",["Examines many genes at once","Needs less starting material","Detects protein as well as RNA","Gives an absolute concentration"],0,"A Northern blot looks at one gene per experiment."),
 ("Compared with a microarray, RNA sequencing has the advantage that it:",["Needs no prior knowledge of sequence","Requires no reverse transcription","Costs substantially less to run","Uses intact tissue without extraction"],0,"An array can only report on the sequences already spotted onto it, so novel transcripts are invisible.",3)],
"clone":[("In molecular cloning, bacterial colonies carrying the plasmid are usually selected using:",["An antibiotic resistance gene","A fluorescent antibody probe","A radioactive DNA probe","A restriction endonuclease"],0,"Only transformed bacteria survive on the selective medium."),
 ("Which enzyme seals the gene into the opened plasmid?",["DNA ligase","DNA polymerase","Restriction endonuclease","Reverse transcriptase"],0,"The restriction enzyme opens it; ligase closes the join."),
 ("RNA interference differs from CRISPR gene editing in that it:",["Silences the gene reversibly","Acts directly on genomic DNA","Requires a guide protein","Works only in bacteria"],0,"Destroying the messenger leaves the gene itself untouched, so the effect lasts only as long as the agent is present.",3)],
}
